<script>
window.SALE_INVOICE_CONFIG={projectId:<?php echo json_encode((int)($projectid??0));?>,companyId:<?php echo json_encode((int)($companyid??0));?>,subcompanyId:<?php echo json_encode((int)($subcompanyid??0));?>};
(function($){'use strict';const C=window.SALE_INVOICE_CONFIG;let rows=[],generated=[];const e=v=>$('<div>').text(v==null?'':String(v)).html(),m=v=>(parseFloat(v)||0).toFixed(2),opts=(a,label)=>'<option value="">'+label+'</option>'+[...new Set(a.map(v=>String(v||'').trim()).filter(Boolean))].sort().map(v=>'<option value="'+e(v)+'">'+e(v)+'</option>').join('');function today(){let d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function load(){$.post('ajax/module.php',{action:'list',projectid:C.projectId},null,'json').done(r=>{if(!r.status){Swal.fire('Sale Invoice',r.message,'error');return}rows=r.data.pending||[];generated=r.data.generated||[];renderFilters();filter();renderGenerated();}).fail(x=>Swal.fire('Sale Invoice',x.responseJSON?.message||'Unable to load data.','error'));}
function renderFilters(){let clients={};rows.forEach(x=>clients[x.clientid]=x.clientname||x.clientid);$('#si_client').html('<option value="">All Clients</option>'+Object.keys(clients).map(k=>'<option value="'+e(k)+'">'+e(clients[k])+'</option>').join(''));$('#si_vehicle').html(opts(rows.map(x=>x.vehicle_no),'All Vehicles'));$('#si_driver').html(opts(rows.map(x=>x.driver_name),'All Drivers'));}
function filter(){let q=String($('#si_search').val()||'').toLowerCase(),c=$('#si_client').val(),v=$('#si_vehicle').val(),d=$('#si_driver').val(),h='';rows.forEach((x,i)=>{let t=[x.clientname,x.clientid,x.psono,x.sono,x.productname,x.productid,x.trip_id,x.vehicle_no,x.driver_name].join(' ').toLowerCase();if((c&&x.clientid!==c)||(v&&x.vehicle_no!==v)||(d&&x.driver_name!==d)||(q&&!t.includes(q)))return;h+='<tr><td class="text-center"><input class="si-check" type="checkbox" data-i="'+i+'"></td><td><b>'+e(x.clientname||x.clientid)+'</b><br><small>PSO: '+e(x.psono)+' • SO: '+e(x.sono)+'</small></td><td><b>'+e(x.productname)+'</b><br><small>'+e(x.productid)+'</small></td><td><b>'+e(x.trip_id)+'</b><br><small>'+e(x.vehicle_no||'-')+' • '+e(x.driver_name||'-')+'</small></td><td class="text-right">'+e(x.dispatched_qty)+'</td><td class="si-money">'+m(x.rate)+'</td><td class="si-money">'+m(x.discount_percent)+'%</td><td class="si-money">'+m(x.line_amount)+'</td></tr>';});$('#si_rows').html(h||'<tr><td colspan="8" class="text-center text-muted">No eligible dispatched products pending invoicing.</td></tr>');update();}
function selected(){return $('.si-check:checked').map(function(){return rows[+$(this).data('i')]}).get().filter(Boolean)}function update(){let a=selected();$('#si_count').text(a.length+' product line(s) selected');$('#si_qty').text(a.reduce((s,x)=>s+(+x.dispatched_qty||0),0));$('#si_amount').text(m(a.reduce((s,x)=>s+(+x.line_amount||0),0)));$('#si_review').prop('disabled',!a.length);}
$(document).on('change','.si-check',function(){let x=rows[+$(this).data('i')],a=selected().filter(y=>y!==x);if(this.checked&&a.some(y=>String(y.clientid)!==String(x.clientid))){this.checked=false;Swal.fire('One Client Only','Select dispatched products belonging to the same client.','warning')}update()});
function review(){let a=selected();if(!a.length)return;$('#sim_client').val(a[0].clientname||a[0].clientid);$('#sim_date').val($('#sim_date').val()||today());$('#sim_remarks').val('');$('#sim_rows').closest('table').find('thead').html('<tr><th>PSO / Product</th><th>Trip</th><th>Invoice Qty</th><th>Invoice Rate</th><th class="text-right">Gross</th><th>Discount %</th><th>Discount Amt</th><th class="text-right">Taxable</th><th>CGST %</th><th>SGST %</th><th>IGST %</th><th class="text-right">Tax Amt</th><th class="text-right">Net</th></tr>');let h='';a.forEach(x=>{let i=rows.indexOf(x),gross=(+x.dispatched_qty||0)*(+x.rate||0),disc=gross*(+x.discount_percent||0)/100;h+='<tr class="sim-line" data-i="'+i+'"><td><b>'+e(x.psono)+'</b><br>'+e(x.productname)+'</td><td>'+e(x.trip_id)+'</td><td><input type="text" inputmode="numeric" pattern="[0-9]*" maxlength="10" class="form-control form-control-sm sim-input sim-qty" value="'+e(x.dispatched_qty)+'" autocomplete="off"><small class="sim-original">Available: '+e(x.dispatched_qty)+'</small></td><td><input type="number" class="form-control form-control-sm sim-input sim-rate" min="0" step="0.01" value="'+m(x.rate)+'"><small class="sim-original">Order: ₹ '+m(x.rate)+'</small></td><td class="si-money sim-gross">'+m(gross)+'</td><td><input type="number" class="form-control form-control-sm sim-input sim-dp" min="0" max="100" step="0.01" value="'+m(x.discount_percent)+'"></td><td><input type="number" class="form-control form-control-sm sim-input sim-da" min="0" step="0.01" value="'+m(disc)+'"></td><td class="si-money sim-taxable">0.00</td><td><input type="number" class="form-control form-control-sm sim-input sim-cg" min="0" max="100" step="0.01" value="0"></td><td><input type="number" class="form-control form-control-sm sim-input sim-sg" min="0" max="100" step="0.01" value="0"></td><td><input type="number" class="form-control form-control-sm sim-input sim-ig" min="0" max="100" step="0.01" value="0"></td><td class="si-money sim-taxamt">0.00</td><td class="si-money sim-net">0.00</td></tr>'});$('#sim_rows').html(h);recalc();$('#si_modal').addClass('open');$('body').css('overflow','hidden');}
function recalc(){let ps={},total=0;$('.sim-line').each(function(){let $r=$(this),x=rows[+$r.data('i')],qty=Math.max(0,parseInt($r.find('.sim-qty').val(),10)||0),rate=Math.max(0,parseFloat($r.find('.sim-rate').val())||0),gross=qty*rate,da=Math.max(0,Math.min(gross,parseFloat($r.find('.sim-da').val())||0)),taxable=gross-da,cg=Math.max(0,parseFloat($r.find('.sim-cg').val())||0),sg=Math.max(0,parseFloat($r.find('.sim-sg').val())||0),ig=Math.max(0,parseFloat($r.find('.sim-ig').val())||0),tax=taxable*(cg+sg+ig)/100,net=taxable+tax;$r.find('.sim-gross').text(m(gross));$r.find('.sim-taxable').text(m(taxable));$r.find('.sim-taxamt').text(m(tax));$r.find('.sim-net').text(m(net));if(!ps[x.psono])ps[x.psono]={total:0,available:+x.available_advance||0};ps[x.psono].total+=net;total+=net});let advance=0;Object.keys(ps).forEach(p=>advance+=Math.min(ps[p].total,ps[p].available));$('#sim_total').text(m(total));$('#sim_advance').text(m(advance));$('#sim_balance').text(m(total-advance));}
$(document).on('keydown','.sim-qty',function(ev){if(['e','E','+','-','.',',',' '].includes(ev.key))ev.preventDefault()}).on('input','.sim-qty',function(){this.value=String(this.value).replace(/\D/g,'').slice(0,10);let $r=$(this).closest('.sim-line'),gross=(parseInt(this.value,10)||0)*(parseFloat($r.find('.sim-rate').val())||0),dp=parseFloat($r.find('.sim-dp').val())||0;$r.find('.sim-da').val(m(gross*dp/100));recalc()}).on('input','.sim-rate',function(){let $r=$(this).closest('.sim-line'),gross=(parseInt($r.find('.sim-qty').val(),10)||0)*(parseFloat(this.value)||0),dp=parseFloat($r.find('.sim-dp').val())||0;$r.find('.sim-da').val(m(gross*dp/100));recalc()}).on('input','.sim-dp',function(){let $r=$(this).closest('.sim-line'),gross=(parseInt($r.find('.sim-qty').val(),10)||0)*(parseFloat($r.find('.sim-rate').val())||0),dp=Math.min(100,Math.max(0,parseFloat(this.value)||0));$r.find('.sim-da').val(m(gross*dp/100));recalc()}).on('input','.sim-da',function(){let $r=$(this).closest('.sim-line'),gross=(parseInt($r.find('.sim-qty').val(),10)||0)*(parseFloat($r.find('.sim-rate').val())||0),da=Math.min(gross,Math.max(0,parseFloat(this.value)||0));$r.find('.sim-dp').val(m(gross?da/gross*100:0));recalc()}).on('input','.sim-cg,.sim-sg',function(){let $r=$(this).closest('.sim-line');if((parseFloat(this.value)||0)>0)$r.find('.sim-ig').val(0);recalc()}).on('input','.sim-ig',function(){let $r=$(this).closest('.sim-line');if((parseFloat(this.value)||0)>0)$r.find('.sim-cg,.sim-sg').val(0);recalc()});
function close(){$('#si_modal').removeClass('open');$('body').css('overflow','')}$('.si-close,.si-back').on('click',close);$('#si_review').on('click',review);$('#sim_save').on('click',function(){let date=$('#sim_date').val(),lines=[],invalid='';$('#sim_warning').text('');$('.sim-line').each(function(){let $r=$(this),x=rows[+$r.data('i')],rawQty=String($r.find('.sim-qty').val()||''),qty=parseInt(rawQty,10)||0,rate=parseFloat($r.find('.sim-rate').val())||0,dp=parseFloat($r.find('.sim-dp').val())||0,da=parseFloat($r.find('.sim-da').val())||0,cg=parseFloat($r.find('.sim-cg').val())||0,sg=parseFloat($r.find('.sim-sg').val())||0,ig=parseFloat($r.find('.sim-ig').val())||0,type=ig>0?'IGST':((cg>0||sg>0)?'CGST_SGST':'NONE');if(!/^\d+$/.test(rawQty)||qty<1||qty>(+x.dispatched_qty||0))invalid='Invoice Qty accepts whole numbers only and must not exceed available dispatched quantity.';if((ig>0)&&(cg>0||sg>0))invalid='Use either CGST + SGST or IGST, not both.';lines.push({line_key:x.line_key,scan_ids:String(x.scan_ids).split(',').map(Number),qty:qty,rate:rate,discount_percent:dp,discount_amount:da,tax_type:type,cgst_percent:cg,sgst_percent:sg,igst_percent:ig})});if(!date)invalid='Invoice Date is required.';if(invalid){$('#sim_warning').text(invalid);return}let qty=lines.reduce((s,x)=>s+x.qty,0);Swal.fire({icon:'question',title:'Create Sale Invoice?',html:'Invoice <b>'+qty+'</b> plants for <b>₹ '+e($('#sim_total').text())+'</b>?',showCancelButton:true,confirmButtonText:'Create Invoice',target:document.body}).then(z=>{if(!z.isConfirmed)return;let b=$('#sim_save').prop('disabled',true);$.post('ajax/module.php',{action:'save',projectid:C.projectId,companyid:C.companyId,subcompanyid:C.subcompanyId,invoice_date:date,remarks:$('#sim_remarks').val(),invoice_lines:JSON.stringify(lines)},null,'json').done(r=>{if(!r.status){Swal.fire('Invoice Not Created',r.message,'error');return}close();
Swal.fire({icon:'success',title:'Sale Invoice Created',html:'<b>'+e(r.data.invoice_no)+'</b><br>Invoice: ₹ '+m(r.data.invoice_amount)+'<br>Tax: ₹ '+m(r.data.tax_amount)+'<br>Advance: ₹ '+m(r.data.advance_applied)+'<br>Balance: ₹ '+m(r.data.balance),showCancelButton:true,confirmButtonText:'Download Invoice PDF',cancelButtonText:'Close',reverseButtons:true,target:document.body}).then(z=>{if(z.isConfirmed){window.open(r.data.download_url||('prints/invoice.php?invoice_id='+encodeURIComponent(r.data.invoice_id)+'&mode=download'),'_blank')}});
load()}).fail(x=>Swal.fire('Invoice Not Created',x.responseJSON?.message||'Unable to create invoice.','error')).always(()=>b.prop('disabled',false));})});
function renderGenerated(){let clients={};generated.forEach(x=>clients[x.clientid]=x.clientname||x.clientid);$('#sig_client').html('<option value="">All Clients</option>'+Object.keys(clients).map(k=>'<option value="'+e(k)+'">'+e(clients[k])+'</option>').join(''));$('#sig_vehicle').html(opts(generated.flatMap(x=>String(x.vehicle_no||'').split(',').map(v=>v.trim())),'All Vehicles'));$('#sig_driver').html(opts(generated.flatMap(x=>String(x.driver_name||'').split(',').map(v=>v.trim())),'All Drivers'));filterGenerated()}
function filterGenerated(){let q=String($('#sig_search').val()||'').toLowerCase(),c=$('#sig_client').val(),v=$('#sig_vehicle').val(),d=$('#sig_driver').val(),h='';generated.forEach(x=>{let vs=String(x.vehicle_no||'').split(',').map(z=>z.trim()),ds=String(x.driver_name||'').split(',').map(z=>z.trim()),txt=[x.invoice_no,x.clientname,x.clientid,x.trip_ids,x.vehicle_no,x.driver_name].join(' ').toLowerCase();if((c&&x.clientid!==c)||(v&&!vs.includes(v))||(d&&!ds.includes(d))||(q&&!txt.includes(q)))return;let url='prints/invoice.php?invoice_id='+encodeURIComponent(x.invoice_id)+'&mode=inline',download='prints/invoice.php?invoice_id='+encodeURIComponent(x.invoice_id)+'&mode=download';h+='<tr><td><b>'+e(x.invoice_no)+'</b></td><td>'+e(x.invoice_date)+'</td><td><b>'+e(x.clientname||x.clientid)+'</b><br><small>'+e(x.clientid)+'</small></td><td>'+e(x.trip_ids)+'</td><td><b>'+e(x.vehicle_no||'-')+'</b><br><small>'+e(x.driver_name||'-')+'</small></td><td class="si-money">'+e(x.total_qty)+'</td><td class="si-money">'+m(x.invoice_amount)+'</td><td class="si-generated"><a class="btn btn-sm btn-outline-primary" target="_blank" href="'+url+'">View / Print</a><a class="btn btn-sm btn-outline-success" target="_blank" href="'+download+'">Download PDF</a></td></tr>'});$('#sig_rows').html(h||'<tr><td colspan="8" class="text-center text-muted">No generated sale invoices for the selected filters.</td></tr>')}
$('#si_search').on('input',filter);$('#si_client,#si_vehicle,#si_driver').on('change',filter);$('#sig_search').on('input',filterGenerated);$('#sig_client,#sig_vehicle,#sig_driver').on('change',filterGenerated);$('#si_all').on('change',function(){let vis=$('.si-check:visible');if(!this.checked){vis.prop('checked',false);update();return}let first=vis.first();if(!first.length)return;let cid=rows[+first.data('i')].clientid;vis.each(function(){this.checked=rows[+$(this).data('i')].clientid===cid});update()});$('.si-tabs button').on('click',function(){let t=$(this).data('tab');$('.si-tabs button').removeClass('btn-primary').addClass('btn-outline-primary');$(this).addClass('btn-primary').removeClass('btn-outline-primary');$('#si_pending').toggle(t==='pending');$('#si_generated').toggle(t==='generated')});$('#si_refresh').on('click',load);$(load);
})(jQuery);
</script>
